# Antiquity polity profiles, part 4: Germanic, Nordic, Baltic and the forest zone
from part3 import P, add

add(id="germanic-peoples", name="Germanic peoples", type="tribal peoples", yearsActive="c. 500 BC–AD 5th century",
 summary="The Germanic-speaking tribes of the Jastorf culture and its successors between the Rhine, the Vistula and southern Scandinavia, who defeated Rome in the Teutoburg Forest and remained free beyond the frontier.",
 description="Germanic languages and the Jastorf culture took shape in northern Germany and Denmark around 500 BC. The Cimbri and Teutones migrated south and were destroyed by Marius in 102–101 BC. Caesar fought Ariovistus in 58 BC and bridged the Rhine. Augustus tried to conquer Germania up to the Elbe, but Arminius destroyed Varus's three legions in AD 9, and the Rhine–Danube frontier was fixed. Tacitus's Germania (AD 98) lists dozens of tribes, among them the Cherusci, Chatti, Suebi, Angles, Frisians and Saxons, which in the third century formed new confederations such as the Franks and Alamanni.",
 conflicts="The Cimbrian War (113–101 BC); Caesar against Ariovistus (58 BC); the Teutoburg Forest (AD 9); Germanicus's campaigns (14–16); raids across the Rhine and the fall of the Limes in the 260s.",
 leaders="Ariovistus of the Suebi; Arminius of the Cherusci; Civilis of the Batavi, who rebelled in 69.",
 religion="Gods such as Wodan, Donar and Tiwaz; Tacitus describes the goddess Nerthus and sacred groves; offerings were put in bogs.",
 culture="Farming villages of longhouses; assemblies (things) of free warriors; chieftains with retinues (comitatus).",
 literature="Oral; the earliest runic inscriptions appear in the second century AD.",
 art="Bog finds such as the Gundestrup cauldron (in Denmark) and the Thorsberg and Nydam deposits.",
 ideas="Tacitus held up the Germans as a mirror to Roman decadence.",
 science="Iron from bog ore; boats such as the Hjortspring boat (c. 350 BC).",
 story=[{"title":"Give me back my legions","text":"When news of the Teutoburg disaster reached Rome, Suetonius says Augustus beat his head against a door crying, 'Quinctilius Varus, give me back my legions!' The numbers of the lost legions were never used again."}],
 sources="Encyclopaedia Britannica, 'Germanic peoples'; M. Todd, The Early Germans (2nd ed. 2004); Tacitus, Germania.",
 images=[("Hjortspring boat","Replica of the Hjortspring boat (c. 350 BC)","culture"),
         ("Kalkriese mask","Roman cavalry mask from the Kalkriese battlefield","art")])

add(id="marcomanni", name="Marcomanni", type="tribal kingdom", yearsActive="c. 9 BC–AD 4th century",
 summary="The Suebian people who moved into Bohemia under King Maroboduus around 9 BC and later led the Marcomannic Wars against Marcus Aurelius.",
 description="Maroboduus led the Marcomanni from the Main region into Bohemia (Boiohaemum, the former land of the Boii) and built the first large Germanic kingdom, with a standing army. Rome planned to invade it in AD 6 but was stopped by the Illyrian revolt. Maroboduus was defeated by Arminius and fled to Roman exile in 19. In 166 the Marcomanni and Quadi broke across the Danube and reached Aquileia, starting fourteen years of war.",
 conflicts="Wars with Arminius (17); the Marcomannic Wars (166–180).",
 leaders="Maroboduus (c. 9 BC–AD 19); Ballomar, who led the invasion of 166/167.",
 religion="Suebian Germanic religion; Tacitus describes the Semnones' sacred grove as the cult centre of the Suebi.",
 culture="Roman goods reached Bohemian chieftains through trade and subsidies.",
 literature="Known from Velleius Paterculus, Tacitus and the Historia Augusta.",
 art="Marcus Aurelius' column in Rome shows the war against them.",
 ideas="Maroboduus's kingdom showed Rome that Germanic peoples could build states.",
 science="Roman-style buildings appear in the Marcomannic area near the Danube.",
 story=[{"title":"The rain miracle","text":"During the war with the Quadi, a Roman army trapped without water was saved by a sudden storm. The Column of Marcus Aurelius shows the rain god pouring down water; Christians later claimed the miracle for their prayers."}],
 sources="Encyclopaedia Britannica, 'Marcomanni'; Tacitus, Annals 2.",
 images=[("Column of Marcus Aurelius rain miracle","The Column of Marcus Aurelius in Rome, which records the Marcomannic Wars","art")])

add(id="goths", name="Goths", type="tribal confederation", yearsActive="1st–5th century AD (as a people north of the frontier)",
 nameByTick={"100": "Goths (Wielbark culture)"},
 summary="The Germanic people of the Wielbark culture on the lower Vistula, who moved south-east to the Black Sea in the third century and created the Chernyakhov culture.",
 description="Roman writers place the Gutones near the Vistula in the first century AD, matching the Wielbark culture. In the late second and third centuries they moved south-east to the Black Sea steppe. They defeated and killed the emperor Decius at Abritus in 251, and raided the Aegean by sea. By 300 the Tervingi and Greuthungi controlled a mixed Chernyakhov culture from the Danube to the Don.",
 conflicts="Abritus (251); the sea raids of the 250s–260s; Claudius II's victory at Naissus (268/269).",
 leaders="Cniva, victor at Abritus; later kings such as Ermanaric.",
 religion="Germanic paganism until Ulfilas converted many to Arian Christianity in the fourth century.",
 culture="Wielbark burials, often without weapons, and stone circles in Pomerania such as Odry and Węsiory.",
 literature="Ulfilas's Gothic Bible (fourth century) is the oldest long text in a Germanic language.",
 art="Brooches and Roman imports in Wielbark and Chernyakhov graves.",
 ideas="Jordanes's Getica (551) told a migration legend from Scandinavia.",
 science="Chernyakhov villages used the potter's wheel and Roman-style farming.",
 story=[{"title":"The death of Decius","text":"In 251 the emperor Decius pursued Goths returning from a raid and was trapped in a marsh at Abritus in Bulgaria. He and his son died, the first Roman emperor to be killed by a foreign enemy."}],
 sources="Encyclopaedia Britannica, 'Goth'; P. Heather, The Goths (1996).",
 images=[("Węsiory stone circles","Gothic stone circles at Węsiory, Pomerania","culture")])

add(id="przeworsk", name="Przeworsk culture (Vandals and Lugii)", type="archaeological culture",
 yearsActive="c. 200 BC–AD 5th century",
 summary="The Iron Age culture of southern and central Poland, usually linked with the Lugii and the Vandals, whose warriors were buried with weapons.",
 description="The Przeworsk culture developed around 200 BC from earlier local cultures with strong Celtic influence. Classical writers place the Lugii federation and the Vandals in this area. Its people farmed, smelted iron on a huge scale in the Holy Cross Mountains and traded on the Amber Road. In the third century Vandal groups moved south toward the Danube.",
 conflicts="Vandals and Lugii took part in the Marcomannic Wars.",
 leaders="Tribal leaders are rarely named; the Hasdingi Vandals had kings Raus and Raptus around 171.",
 religion="Cremation burial, often with deliberately bent weapons.",
 culture="Villages of farmers and smiths; Roman coins and bronze vessels reached elites.",
 literature="Known from Tacitus, Ptolemy and Cassius Dio.",
 art="Decorated spurs, swords and brooches.",
 ideas="Archaeologists link it with the Vandals, but the link is debated.",
 science="The Holy Cross Mountains iron district held thousands of bloomery furnaces.",
 story=[{"title":"Bent swords","text":"Przeworsk warriors were often cremated with their swords bent or broken, perhaps to 'kill' the weapon so it followed its owner or could not be used again."}],
 sources="Encyclopaedia Britannica, 'Vandal'; P. Heather, Empires and Barbarians (2009).",
 images=[("Przeworsk culture","Finds of the Przeworsk culture","culture")])

add(id="pomeranian-culture", name="Pomeranian culture", type="archaeological culture", yearsActive="c. 650–150 BC",
 summary="The Early Iron Age culture of northern Poland, known for its face urns and stone-cist graves, which spread south across Poland before the Przeworsk and Jastorf cultures replaced it.",
 description="The Pomeranian culture emerged in Gdańsk Pomerania around 650 BC and spread south over much of Poland. Its people buried the ashes of the dead in urns with human faces, placed in stone cists (box graves), which gives its alternative name 'bell-grave' or cist-grave culture. It faded in the second century BC.",
 conflicts="Little is known of its conflicts; Scythian arrowheads in the Lusatian area show raids around 500 BC.",
 leaders="No individuals are known.",
 religion="Face urns may have represented the dead person or an ancestor.",
 culture="Farming villages; amber trade along the Vistula.",
 literature="None.",
 art="Face urns with ears, sometimes with earrings and incised jewellery.",
 ideas="Its ethnic identity is unknown.",
 science="Bronze and early iron working.",
 story=[{"title":"Faces of the dead","text":"Some face urns wear real bronze earrings in pierced clay ears, as if dressed for the grave."}],
 sources="Encyclopaedia Britannica, 'Pomeranian culture'; P. Urbańczyk (ed.), archaeological surveys of Iron Age Poland.",
 images=[("Face urn Pomeranian culture","A face urn of the Pomeranian culture","art")])

add(id="scandinavians", name="Iron Age Scandinavia", type="tribal peoples", yearsActive="c. 500 BC–AD 400",
 summary="The farming chiefdoms of Denmark, Sweden and Norway in the pre-Roman and Roman Iron Ages, ancestors of the Norse, including the Heruli and Suiones.",
 description="After the Bronze Age, Scandinavia entered the pre-Roman Iron Age around 500 BC. In the Roman Iron Age (from c. AD 1) chieftains acquired Roman weapons, glass and silver, and Tacitus mentions the Suiones with their fleets. Great deposits of weapons in Danish bogs, such as Illerup Ådal (c. 205), record battles with invaders. The Heruli appear in the third century raiding the Black Sea alongside the Goths.",
 conflicts="Battles recorded by bog weapon deposits at Illerup, Nydam and Ejsbøl.",
 leaders="Unknown by name.",
 religion="Bog offerings, including human sacrifices such as Tollund Man (c. 400 BC).",
 culture="Longhouse farms; chieftain centres such as Gudme on Funen.",
 literature="The runic script appears around AD 150.",
 art="The Gundestrup cauldron and Roman-era gold neck rings.",
 ideas="Later Norse myths may preserve older beliefs.",
 science="Iron from bog ore; boats such as the Nydam boat.",
 story=[{"title":"Tollund Man","text":"In 1950 peat cutters in Denmark found a man so well preserved they thought he was a recent murder victim. He had been hanged around 400 BC and laid in the bog, perhaps as a sacrifice."}],
 sources="Encyclopaedia Britannica, 'Scandinavia: Iron Age'; L. Hedeager, Iron-Age Societies (1992).",
 images=[("Tollund Man","Tollund Man (c. 400 BC), Silkeborg Museum","culture")])

add(id="balts", name="Baltic peoples", type="tribal peoples", yearsActive="c. 1000 BC–AD 13th century",
 summary="The ancestors of the Prussians, Lithuanians, Latvians and Curonians on the south-east Baltic coast, known to the Romans as the Aesti and as sources of amber.",
 description="Baltic-speaking peoples lived from the Vistula to the Daugava and inland. Archaeologists divide them into regional cultures, such as the Brushed Pottery culture of Lithuania and Belarus and the West Baltic Barrow culture of Masuria and Sambia. Tacitus describes the Aesti gathering amber on the shore. The Amber Road carried Baltic amber to Aquileia, and Roman coins and brooches flowed back.",
 conflicts="Little recorded.",
 leaders="Unknown by name.",
 religion="Nature gods and sacred groves.",
 culture="Hill-forts and fortified settlements; amber gathering.",
 literature="Baltic languages are among the most archaic Indo-European languages.",
 art="Enamelled bronze ornaments of the Roman Iron Age.",
 ideas="Tacitus says the Aesti were surprised at the price Romans paid for amber.",
 science="Amber collection and trade.",
 story=[{"title":"Amber for Nero","text":"Pliny tells of a Roman knight sent by Nero to the Baltic coast who brought back so much amber that the nets protecting the arena and the gladiators' weapons were decorated with it."}],
 sources="Encyclopaedia Britannica, 'Balt'; M. Gimbutas, The Balts (1963).",
 images=[("Baltic amber","Baltic amber","culture")])

add(id="dnieper-dvina", name="Dnieper–Dvina culture", type="archaeological culture", yearsActive="c. 8th century BC–AD 4th century",
 summary="The Iron Age culture of hill-forts on the upper Dnieper and Western Dvina, in Belarus and western Russia, usually linked with eastern Baltic speakers.",
 description="The Dnieper–Dvina culture is known for small hill-forts on river bluffs and for plain hand-made pottery. Its people kept livestock and farmed clearings in the forest. Many scholars link it with Baltic-speaking peoples who lived far east of today's Baltic states.",
 conflicts="Unknown.",
 leaders="Unknown.",
 religion="Unknown.",
 culture="Fortified hill-forts with wooden walls.",
 literature="None.",
 art="Simple bronze and iron ornaments.",
 ideas="River names of Baltic origin in the region support the link with Baltic speakers.",
 science="Bog iron smelting.",
 story=[{"title":"Baltic rivers in Russia","text":"Linguists found river names of Baltic origin across a wide area of Belarus and western Russia, showing that Baltic speakers once lived far to the east."}],
 sources="M. Gimbutas, The Balts (1963); J. P. Mallory and D. Q. Adams (eds.), Encyclopedia of Indo-European Culture (1997).",
 images=[("Western Dvina Vitebsk","The Western Dvina at Vitebsk, in the heartland of the culture","culture")])

add(id="milograd", name="Milograd culture", type="archaeological culture", yearsActive="c. 7th–1st century BC",
 summary="The Iron Age culture of southern Belarus and northern Ukraine, sometimes identified with Herodotus's Neuri.",
 description="The Milograd culture lived in fortified settlements in the Pripet and upper Dnieper region. Archaeologists have linked it with the Neuri, a people Herodotus places north of the Scythians, about whom he tells the story that they became wolves for a few days each year.",
 conflicts="Unknown.",
 leaders="Unknown.",
 religion="Herodotus's werewolf tale may reflect a ritual.",
 culture="Fortified settlements and farming.",
 literature="Herodotus, book 4.",
 art="Pottery with rounded bases.",
 ideas="Its ethnic identity (Baltic or early Slavic) is debated.",
 science="Iron working.",
 story=[{"title":"The Neuri","text":"Herodotus heard from Greeks and Scythians that each Neurian turned into a wolf for a few days every year. He says he did not believe it."}],
 sources="Herodotus, Histories 4.105; Encyclopaedia Britannica, 'Neuri'.",
 images=[("Herodotus world map","Reconstruction of the world as Herodotus described it, with the Neuri north of Scythia","culture")])

add(id="finno-ugric", name="Finno-Ugric peoples", type="tribal peoples", yearsActive="prehistory–present",
 summary="The hunters, fishers and farmers of the northern forest zone, ancestors of the Finns, Estonians, Mari and other Uralic-speaking peoples.",
 description="Uralic-speaking peoples lived across the taiga from the Baltic to the Urals. Tacitus mentions the Fenni, who lived by hunting and had no horses or houses. Farming spread slowly northwards, and Estonian coastal peoples built stone-cist graves.",
 conflicts="Unknown.",
 leaders="Unknown.",
 religion="Animism and shamanism.",
 culture="Hunting, fishing and some farming; trade in furs.",
 literature="Tacitus, Germania 46.",
 art="Animal carvings and comb-decorated pottery.",
 ideas="Tacitus admired the Fenni as people who had no need of anything.",
 science="Skis and sledges.",
 story=[{"title":"The Fenni","text":"Tacitus says the Fenni lived in amazing poverty, using arrows tipped with bone and sleeping on the ground, yet thought themselves happier than farmers."}],
 sources="Tacitus, Germania 46; Encyclopaedia Britannica, 'Finno-Ugric peoples'.",
 images=[("Comb Ceramic pottery","Comb Ceramic pottery of the northern forest zone","art")])

add(id="saami", name="Saami", type="tribal peoples", yearsActive="prehistory–present",
 summary="The reindeer-hunting peoples of northern Scandinavia and the Kola Peninsula.",
 description="The Saami lived by hunting wild reindeer, fishing and trapping in the far north. Classical writers may mention them as 'Skrithiphinoi' (ski-running Finns) by the sixth century.",
 conflicts="Unknown.",
 leaders="Unknown.",
 religion="Shamanism with the noaidi and sacred stones (sieidi).",
 culture="Seasonal movement between hunting and fishing grounds.",
 literature="Oral joik song tradition.",
 art="Rock carvings at Alta are older.",
 ideas="Their lands were outside the Roman world.",
 science="Skis and reindeer hunting systems.",
 story=[{"title":"Ski-runners","text":"Procopius in the sixth century described the 'Scrithiphini' of Thule, who lived by hunting and did not farm, probably the Saami."}],
 sources="Encyclopaedia Britannica, 'Sami'; Procopius, Wars 6.15.",
 images=[("Alta rock carvings","Rock carvings at Alta in northern Norway","art")])
